import {FACTORY_PRESETS,applyFactoryPreset} from './bundle.js?v=0.11.1';
import {normalizeNotes,snapStep,snapPitch,quantizeNotes,moveNotes,chordNotes,resolvePatternClip,writePatternChannel,SCALES} from './piano-model.js?v=0.11.1';
import {fitSession} from './studio-model.js?v=0.11.1';
const $=id=>document.getElementById(id),uid=()=>Math.random().toString(36).slice(2,11),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'],noteName=n=>names[n%12]+(Math.floor(n/12)-1),black=n=>[1,3,6,8,10].includes(n%12);
export function installPianoRoll(d){const project=d.getProject,engine=d.getEngine;let selected=new Set(),grid=1,tool='draw',stepWidth=22,noteHeight=18,lastLength=4,scale='minor',root=9,scaleSnap=false,ghost=true,clipboard=[],drag=null,editor=null,editingClip=null,editingTrack=null,draftClip=null,draftTrack=null,midi=null,midiRecord=false,midiHeld=new Map(),scrollTop=null;
  function draft(trackId){return draftTrack===trackId?draftClip:null;}
  function current(){const t=d.currentTrack(),c=d.currentClip();return {t,c};}
  const commit=(redraw=true)=>{if(!editingClip||!editingTrack)return;editingClip.notes=normalizeNotes(editingClip.notes,editingClip.patternSteps||32);writePatternChannel(project(),editingTrack,editingClip);d.changed();if(redraw)renderNotes();d.drawClips();};
  function bank(){project().patterns??=[];if(!project().patterns.length){project().patterns.push({id:uid(),name:'Pattern 1',bars:2,channels:{}});project().activePattern=project().patterns[0].id;}return project().patterns.find(p=>p.id===project().activePattern)||project().patterns[0];}
  function openChannel(t,pattern=bank()){let data=pattern.channels[t.id];if(!data){d.checkpoint();data=t.type==='drums'?{pattern:Object.fromEntries(Object.keys(DRUM_VOICES).map(v=>[v,Array(pattern.bars*16).fill(0)]))}:{notes:[]};pattern.channels[t.id]=data;}if(document.querySelector('.detail-panel').getBoundingClientRect().height<350)document.documentElement.style.setProperty('--detail-height',Math.min(innerHeight*.55,500)+'px');draftTrack=t.id;draftClip={id:'draft'+pattern.id+t.id,patternId:pattern.id,name:pattern.name,start:0,length:pattern.bars,patternSteps:pattern.bars*16,...structuredClone(data)};d.openEditor(t.id,null);$('modal').close();d.save();}
  function placePattern(){const pattern=bank(),at=Math.floor(engine().getPosition()/16);if(at+pattern.bars>2048)return;let count=0;d.checkpoint();for(const t of project().tracks){const channel=pattern.channels[t.id];if(!channel)continue;const hasData=t.type==='drums'?Object.values(channel.pattern||{}).some(row=>row.some(Boolean)):channel.notes?.length;if(!hasData)continue;t.clips.push({id:uid(),name:pattern.name,start:at,length:pattern.bars,patternId:pattern.id,patternSteps:pattern.bars*16,...structuredClone(channel)});count++;}project().bars=fitSession(project().bars,at+pattern.bars);d.changed(true);d.toast(count?pattern.name+' placé sur '+count+' piste(s).':'Ajoute des notes ou des pas à ce pattern.');}
  function rack(){const pattern=bank(),tracks=project().tracks.filter(t=>INSTRUMENTS[t.type]);d.modal('Channel Rack · '+pattern.name,`<div class="channel-rack"><div class="rack-toolbar"><select id="patternSelect" aria-label="Pattern actif">${project().patterns.map(p=>`<option value="${p.id}" ${p.id===pattern.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button id="newPattern" class="outline-btn">+ Pattern</button><button id="clonePattern" class="outline-btn">Dupliquer</button><input id="patternName" value="${esc(pattern.name)}" aria-label="Nom du pattern" maxlength="50"><select id="rackBars" aria-label="Longueur du pattern">${[1,2,4,8,16,32].map(b=>`<option value="${b}" ${b===pattern.bars?'selected':''}>${b} mesure(s)</option>`).join('')}</select></div><div class="rack-rows">${tracks.map(t=>{const data=pattern.channels[t.id];return `<div class="rack-channel" style="--track-color:${t.color}"><button data-rack-open="${t.id}" class="rack-channel-name">${esc(t.name)}<small>${INSTRUMENTS[t.type].name}</small></button><select data-rack-preset="${t.id}" aria-label="Son de ${esc(t.name)}"><option value="">Choisir un son…</option>${FACTORY_PRESETS[t.type].map((a,i)=>`<option value="${i}">${esc(a.name)}</option>`).join('')}</select><button class="outline-btn" data-rack-open="${t.id}">${t.type==='drums'?'Step sequencer':'Piano roll'} · ${t.type==='drums'?Object.values(data?.pattern||{}).reduce((a,v)=>a+v.filter(Boolean).length,0):data?.notes?.length||0}</button><button class="outline-btn" data-rack-plugin="${t.id}">Instrument</button></div>`;}).join('')||'<p>Ajoute un instrument pour commencer. Les inserts de mix restent vides.</p>'}</div><div class="rack-add"><select id="rackInstrument" aria-label="Instrument à ajouter">${Object.entries(INSTRUMENTS).map(([id,v])=>`<option value="${id}">${v.name} · ${v.subtitle}</option>`).join('')}</select><button id="rackAddInstrument" class="primary-btn">+ Ajouter un canal</button></div><div class="rack-toolbar"><button id="previewPattern" class="outline-btn">▶ Écouter en mode PAT</button><button id="stopPattern" class="outline-btn">■ Arrêter</button><button id="placePattern" class="primary-btn">Placer en Playlist au curseur</button></div><p>Écris un pattern, écoute-le en boucle puis place-le dans l’arrangement. Les copies restent liées : modifier le pattern met à jour ses clips.</p></div>`,'WARLIKE / BEATMAKING');
    $('patternSelect').onchange=e=>{engine().pause();project().activePattern=e.target.value;engine().patternMode=e.target.value;engine().clipPreview=null;d.save();rack();};$('newPattern').onclick=()=>{d.checkpoint();const next={id:uid(),name:'Pattern '+(project().patterns.length+1),bars:2,channels:{}};project().patterns.push(next);project().activePattern=next.id;d.changed();rack();};$('clonePattern').onclick=()=>{d.checkpoint();const next={...structuredClone(pattern),id:uid(),name:pattern.name+' · copie'};project().patterns.push(next);project().activePattern=next.id;d.changed();rack();};$('patternName').onchange=e=>{d.checkpoint();pattern.name=e.target.value.trim()||pattern.name;d.changed();};$('rackBars').onchange=e=>{d.checkpoint();pattern.bars=Number(e.target.value);for(const t of tracks){const data=pattern.channels[t.id];if(data?.notes)data.notes=normalizeNotes(data.notes,pattern.bars*16);for(const c of t.clips)if(c.patternId===pattern.id){Object.assign(c,data);c.patternSteps=pattern.bars*16;}}d.changed(true);rack();};
    $('rackAddInstrument').onclick=()=>{const t=d.addTrack($('rackInstrument').value);pattern.channels[t.id]=t.type==='drums'?{pattern:Object.fromEntries(Object.keys(DRUM_VOICES).map(v=>[v,Array(pattern.bars*16).fill(0)]))}:{notes:[]};rack();};
    for(const b of document.querySelectorAll('[data-rack-open]'))b.onclick=()=>openChannel(project().tracks.find(t=>t.id===b.dataset.rackOpen),pattern);
    for(const b of document.querySelectorAll('[data-rack-plugin]'))b.onclick=()=>{$('modal').close();d.openPlugin('instrument',b.dataset.rackPlugin);};
    for(const input of document.querySelectorAll('[data-rack-preset]'))input.onchange=e=>{if(e.target.value==='')return;const t=project().tracks.find(t=>t.id===input.dataset.rackPreset);d.checkpoint();applyFactoryPreset(t,'instrument',Number(input.value));d.changed();d.toast('Son choisi pour '+t.name+'.');};
    $('previewPattern').onclick=async()=>{engine().pause();engine().patternMode=pattern.id;engine().clipPreview=null;engine().position=0;engine().loop=true;await engine().play();d.updateTransport();};$('stopPattern').onclick=()=>{engine().stop();d.updateTransport();};$('placePattern').onclick=placePattern;
  }
  function render(t,c){if(!c)return false;if(editingClip?.id!==c.id)scrollTop=null;editingTrack=t;editingClip=c;const source=resolvePatternClip(project(),t,c);if(c.patternId&&source!==c){c.notes=source.notes;c.pattern=source.pattern;c.patternSteps=source.patternSteps;}c.patternSteps??=32;c.notes=normalizeNotes(c.notes,c.patternSteps);selected=new Set([...selected].filter(id=>c.notes.some(n=>n.id===id)));root=project().pianoKey??root;scale=project().pianoScale??scale;
    const low=Math.max(0,Math.min(36,...c.notes.map(n=>n.midi))-2),high=Math.min(127,Math.max(84,...c.notes.map(n=>n.midi))+2),rows=high-low+1,width=c.patternSteps*stepWidth,height=rows*noteHeight;
    editor=$('editorContent');editor.innerHTML=`<section class="fl-piano" tabindex="0" aria-label="Piano roll"><div class="pr-toolbar"><strong>PIANO ROLL <span>${esc(t.name)}</span></strong><div class="pr-tools">${[['draw','✎','Dessiner'],['select','▧','Sélectionner'],['erase','⌫','Effacer']].map(([id,icon,name])=>`<button data-pr-tool="${id}" class="${tool===id?'active':''}" title="${name}" aria-label="${name} les notes">${icon}</button>`).join('')}</div><label>Grille<select id="prGrid" aria-label="Grille du piano roll">${[[4,'1/4'],[2,'1/8'],[1,'1/16'],[.5,'1/32'],[1/3,'Triolet'],[0,'Libre']].map(([v,name])=>`<option value="${v}" ${Math.abs(v-grid)<1e-8?'selected':''}>${name}</option>`).join('')}</select></label><button id="prQuantize">Quantifier</button><button id="prDuplicate">Dupliquer</button><button id="prZoomOut" aria-label="Dézoomer le piano roll">−</button><button id="prZoomIn" aria-label="Zoomer le piano roll">+</button><button id="prRack">Channel Rack</button><button id="prExpand">↗ Agrandir</button><button id="prPlay">▶ PAT</button><button id="prMidi">Clavier MIDI</button><button id="prMidiRecord" class="${midiRecord?'recording':''}">● REC MIDI</button></div><div class="pr-musical"><label>Tonalité<select id="prKey">${names.map((n,i)=>`<option value="${i}" ${i===root?'selected':''}>${n}</option>`).join('')}</select></label><select id="prScale" aria-label="Gamme du piano roll"><option value="minor" ${scale==='minor'?'selected':''}>Mineure</option><option value="major" ${scale==='major'?'selected':''}>Majeure</option><option value="chromatic" ${scale==='chromatic'?'selected':''}>Chromatique</option></select><label><input id="prScaleSnap" type="checkbox" ${scaleSnap?'checked':''}> Notes dans la gamme</label><label><input id="prGhost" type="checkbox" ${ghost?'checked':''}> Notes fantômes</label><label>Accord<select id="prChord"><option value="minor">Mineur</option><option value="major">Majeur</option><option value="minor7">Mineur 7</option><option value="major7">Majeur 7</option><option value="sus2">Sus2</option><option value="sus4">Sus4</option></select></label><button id="prStampChord">Insérer l’accord</button><label>Pattern<select id="prLength">${[1,2,4,8,16,32].map(b=>`<option value="${b}" ${b*16===c.patternSteps?'selected':''}>${b} mes.</option>`).join('')}</select></label><span id="prSelectionCount"></span></div><div class="pr-scroll" id="prScroll"><div class="pr-canvas" style="width:${width+52}px;height:${height+23}px"><div class="pr-keyboard" style="height:${height}px;top:23px">${Array.from({length:rows},(_,i)=>high-i).map(n=>`<button class="pr-key ${black(n)?'black':''}" data-pr-key="${n}" style="height:${noteHeight}px" aria-label="Jouer ${noteName(n)}">${noteName(n)}</button>`).join('')}</div><div class="pr-ruler" style="width:${width}px">${Array.from({length:c.patternSteps/16},(_,i)=>`<button data-pr-seek="${i}" style="left:${i*16*stepWidth}px;width:${16*stepWidth}px">${i+1}</button>`).join('')}</div><div id="prGridCanvas" class="pr-grid" data-low="${low}" data-high="${high}" style="left:52px;top:23px;width:${width}px;height:${height}px;--step:${stepWidth}px;--note-height:${noteHeight}px;--beat-width:${stepWidth*4}px;--bar-width:${stepWidth*16}px">${Array.from({length:rows},(_,i)=>high-i).map(n=>`<div class="pr-pitch-row ${black(n)?'black':''} ${SCALES[scale].includes(((n-root)%12+12)%12)?'in-scale':''}" style="top:${(high-n)*noteHeight}px;height:${noteHeight}px"></div>`).join('')}<div id="prGhostNotes"></div><div id="prNotes"></div><div id="prPlayhead" class="pr-playhead"></div><div id="prSelectionBox" hidden></div></div></div></div><div class="pr-velocity-heading">VELOCITY <small>Glisse les barres · Alt + molette sur une note · Ctrl+clic : sélection · bord droit : durée · clic droit : effacer</small></div><div class="pr-velocity-scroll" id="prVelocityScroll"><div id="prVelocities" style="width:${width}px"></div></div></section>`;
    const scroll=$('prScroll');const targetScroll=scrollTop??Math.max(0,(high-72)*noteHeight);requestAnimationFrame(()=>{if(scroll.isConnected)scroll.scrollTop=targetScroll;});scroll.onscroll=()=>{scrollTop=scroll.scrollTop;$('prVelocityScroll').scrollLeft=scroll.scrollLeft;};$('prVelocityScroll').onscroll=()=>scroll.scrollLeft=$('prVelocityScroll').scrollLeft;
    renderNotes();attach(t,c);return true;
  }
  function renderNotes(){if(!$('prNotes')||!editingClip)return;const c=editingClip,high=Number($('prGridCanvas').dataset.high);$('prNotes').innerHTML=c.notes.map(n=>`<button class="pr-note ${selected.has(n.id)?'selected':''} ${n.muted?'muted':''}" data-pr-note="${n.id}" aria-label="${noteName(n.midi)}, pas ${(n.step+1).toFixed(2)}, vélocité ${Math.round(n.velocity*127)}" style="left:${n.step*stepWidth}px;top:${(high-n.midi)*noteHeight+1}px;width:${Math.max(4,n.len*stepWidth-1)}px;height:${noteHeight-2}px;--velocity:${n.velocity}"><span>${noteName(n.midi)}</span><i></i></button>`).join('');
    $('prVelocities').innerHTML=c.notes.map((n,i)=>`<button data-pr-velocity="${n.id}" class="${selected.has(n.id)?'selected':''}" aria-label="Vélocité de ${noteName(n.midi)}" title="${Math.round(n.velocity*127)} / 127" style="left:${n.step*stepWidth+(i%4)*3}px;height:${Math.max(2,n.velocity*58)}px;width:5px"></button>`).join('');$('prSelectionCount').textContent=selected.size?selected.size+' note(s) sélectionnée(s)':c.notes.length+' notes';
    let other=[];if(ghost&&c.patternId){const pattern=project().patterns?.find(p=>p.id===c.patternId);other=Object.entries(pattern?.channels||{}).filter(([id])=>id!==editingTrack.id).flatMap(([,channel])=>channel.notes||[]);}else if(ghost)other=project().tracks.filter(t=>t.id!==editingTrack.id).flatMap(t=>t.clips.filter(a=>!a.audioId&&a.start===c.start).flatMap(a=>a.notes||[]));$('prGhostNotes').innerHTML=other.map(n=>`<div style="left:${n.step*stepWidth}px;top:${(high-n.midi)*noteHeight+2}px;width:${n.len*stepWidth}px;height:${noteHeight-4}px"></div>`).join('');
  }
  function attach(t,c){const gridNode=$('prGridCanvas'),rootNode=editor.querySelector('.fl-piano'),steps=c.patternSteps||32,coordinate=e=>{const r=gridNode.getBoundingClientRect();let step=Math.max(0,Math.min(steps-1/96,snapStep((e.clientX-r.left)/stepWidth,e.altKey?0:grid))),midi=Math.max(0,Math.min(127,Number(gridNode.dataset.high)-Math.floor((e.clientY-r.top)/noteHeight)));if(scaleSnap)midi=snapPitch(midi,root,scale);return {step,midi,x:e.clientX-r.left,y:e.clientY-r.top};};
    const chosen=()=>c.notes.filter(n=>selected.has(n.id)),targets=()=>selected.size?chosen():c.notes,applyNotes=fn=>{d.checkpoint();const ids=new Set(targets().map(n=>n.id));c.notes=c.notes.flatMap(n=>ids.has(n.id)?fn(n):[n]);commit();};
    for(const b of editor.querySelectorAll('[data-pr-tool]'))b.onclick=()=>{tool=b.dataset.prTool;render(t,c);};$('prGrid').onchange=e=>grid=Number(e.target.value);$('prQuantize').onclick=()=>{d.checkpoint();const ids=new Set(targets().map(n=>n.id));c.notes=c.notes.map(n=>ids.has(n.id)?quantizeNotes([n],grid||1,steps)[0]:n);commit();};
    const duplicate=()=>{const notes=targets();if(!notes.length)return;d.checkpoint();const low=Math.min(...notes.map(n=>n.step)),end=Math.max(...notes.map(n=>n.step+n.len)),shift=Math.max(grid||.25,end-low);if(end+shift>steps){d.toast('Agrandis le pattern pour dupliquer cette sélection.');return;}const copies=notes.map(n=>({...n,id:uid(),step:n.step+shift}));c.notes.push(...copies);selected=new Set(copies.map(n=>n.id));commit();};$('prDuplicate').onclick=duplicate;
    $('prExpand').onclick=()=>{document.documentElement.style.setProperty('--detail-height',Math.min(innerHeight*.7,650)+'px');};
    $('prZoomIn').onclick=()=>{stepWidth=Math.min(80,stepWidth*1.25);render(t,c);};$('prZoomOut').onclick=()=>{stepWidth=Math.max(6,stepWidth/1.25);render(t,c);};$('prRack').onclick=rack;
    $('prKey').onchange=e=>{root=Number(e.target.value);project().pianoKey=root;d.save();render(t,c);};$('prScale').onchange=e=>{scale=e.target.value;project().pianoScale=scale;d.save();render(t,c);};$('prScaleSnap').onchange=e=>scaleSnap=e.target.checked;$('prGhost').onchange=e=>{ghost=e.target.checked;renderNotes();};
    $('prStampChord').onclick=()=>{d.checkpoint();const note=chosen()[0],at=note?.step||0,midi=note?.midi||60+root,notes=chordNotes(Math.min(108,midi),$('prChord').value,at,lastLength);c.notes.push(...notes);selected=new Set(notes.map(n=>n.id));commit();};
    $('prLength').onchange=e=>{d.checkpoint();const bars=Number(e.target.value);c.patternSteps=bars*16;c.notes=normalizeNotes(c.notes,c.patternSteps);if(c.patternId){const pattern=project().patterns.find(p=>p.id===c.patternId);pattern.bars=bars;}commit(false);render(t,c);};
    $('prPlay').onclick=async()=>{if(engine().playing){engine().pause();}else{if(c.patternId)engine().patternMode=c.patternId;else{engine().patternMode=null;engine().clipPreview={trackId:t.id,clip:c};}engine().position=0;engine().loop=true;await engine().play();}d.updateTransport();};$('prMidi').onclick=connectMidi;$('prMidiRecord').onclick=async()=>{if(!midi)await connectMidi();if(!midi)return;midiRecord=!midiRecord;if(midiRecord){if(c.patternId)engine().patternMode=c.patternId;else{engine().patternMode=null;engine().clipPreview={trackId:t.id,clip:c};}engine().position=0;engine().loop=true;await engine().play();d.checkpoint();}else{engine().pause();for(const [key,n] of midiHeld)finishMidi(key,n);midiHeld.clear();}d.updateTransport();$('prMidiRecord').classList.toggle('recording',midiRecord);};
    for(const b of editor.querySelectorAll('[data-pr-key]'))b.onpointerdown=()=>engine().preview(t.type,Number(b.dataset.prKey),t.id);
    for(const b of editor.querySelectorAll('[data-pr-seek]'))b.onclick=()=>{engine().seek(Number(b.dataset.prSeek)*16);d.updateTransport();};
    gridNode.oncontextmenu=e=>{e.preventDefault();const node=e.target.closest('[data-pr-note]');if(node){d.checkpoint();c.notes=c.notes.filter(n=>n.id!==node.dataset.prNote);selected.delete(node.dataset.prNote);commit();}else{selected.clear();renderNotes();}};
    gridNode.onpointerdown=e=>{if(e.button!==0)return;rootNode.focus({preventScroll:true});const hit=e.target.closest('[data-pr-note]'),pos=coordinate(e);if(hit){const n=c.notes.find(n=>n.id===hit.dataset.prNote);if(tool==='erase'){d.checkpoint();c.notes=c.notes.filter(a=>a!==n);commit();return;}if(e.ctrlKey||e.metaKey){selected.has(n.id)?selected.delete(n.id):selected.add(n.id);renderNotes();return;}if(!selected.has(n.id)){selected.clear();selected.add(n.id);}d.checkpoint();if(e.shiftKey){const copies=chosen().map(n=>({...n,id:uid()}));c.notes.push(...copies);selected=new Set(copies.map(n=>n.id));}const resize=e.clientX>hit.getBoundingClientRect().right-8;drag={kind:resize?'resize':'move',pointer:e.pointerId,x:e.clientX,y:e.clientY,pos,notes:chosen().map(n=>({...n}))};lastLength=n.len;}
      else if(tool==='select'||e.ctrlKey||e.metaKey){selected.clear();drag={kind:'select',pointer:e.pointerId,pos};}
      else if(tool==='draw'){d.checkpoint();const note={id:uid(),step:pos.step,midi:pos.midi,len:Math.min(lastLength,steps-pos.step),velocity:.8};c.notes.push(note);selected=new Set([note.id]);drag={kind:'new',pointer:e.pointerId,pos,note};commit();}
      gridNode.setPointerCapture(e.pointerId);e.preventDefault();renderNotes();};
    gridNode.onpointermove=e=>{if(!drag||e.pointerId!==drag.pointer)return;const pos=coordinate(e);if(drag.kind==='select'){const a=drag.pos,lo=Math.min(a.step,pos.step),hi=Math.max(a.step,pos.step),bottom=Math.min(a.midi,pos.midi),top=Math.max(a.midi,pos.midi);selected=new Set(c.notes.filter(n=>n.step+n.len>=lo&&n.step<=hi&&n.midi>=bottom&&n.midi<=top).map(n=>n.id));const box=$('prSelectionBox');box.hidden=false;Object.assign(box.style,{left:Math.min(a.x,pos.x)+'px',top:Math.min(a.y,pos.y)+'px',width:Math.abs(a.x-pos.x)+'px',height:Math.abs(a.y-pos.y)+'px'});renderNotes();return;}
      if(drag.kind==='new'){if(Math.abs(pos.step-drag.pos.step)>Math.max(.1,grid/2)){const n=c.notes.find(n=>n.id===drag.note.id);n.len=Math.max(1/96,Math.min(steps-n.step,pos.step-n.step+(grid||.25)));lastLength=n.len;}}
      else{const dx=snapStep((e.clientX-drag.x)/stepWidth,e.altKey?0:grid),dy=-Math.round((e.clientY-drag.y)/noteHeight);let notes=drag.kind==='resize'?drag.notes.map(n=>({...n,len:Math.max(grid||1/96,Math.min(steps-n.step,n.len+dx))})):moveNotes(drag.notes,dx,dy,steps);for(const edited of notes){if(scaleSnap)edited.midi=snapPitch(edited.midi,root,scale);Object.assign(c.notes.find(n=>n.id===edited.id),edited);}}
      commit();};
    const finish=()=>{if(drag){drag=null;if($('prSelectionBox'))$('prSelectionBox').hidden=true;commit();}};gridNode.onpointerup=finish;gridNode.onpointercancel=finish;
    gridNode.ondblclick=e=>{const hit=e.target.closest('[data-pr-note]');if(!hit)return;const n=c.notes.find(n=>n.id===hit.dataset.prNote);d.modal('Note · '+noteName(n.midi),`<div class="workflow-form"><label>Hauteur MIDI<input id="noteMidi" type="number" min="0" max="127" value="${n.midi}"></label><label>Début (pas)<input id="noteStep" type="number" step=".01" min="0" value="${n.step}"></label><label>Durée (pas)<input id="noteDuration" type="number" step=".01" min=".01" value="${n.len}"></label><label>Vélocité (1–127)<input id="noteVelocity" type="number" min="1" max="127" value="${Math.round(n.velocity*127)}"></label><button id="saveNote" class="primary-btn">Appliquer</button></div>`);$('saveNote').onclick=()=>{d.checkpoint();Object.assign(n,{midi:Number($('noteMidi').value),step:Number($('noteStep').value),len:Number($('noteDuration').value),velocity:Number($('noteVelocity').value)/127});commit();$('modal').close();};};
    gridNode.onwheel=e=>{const hit=e.target.closest('[data-pr-note]');if(!hit||!e.altKey)return;e.preventDefault();d.checkpoint();const n=c.notes.find(n=>n.id===hit.dataset.prNote),notes=selected.has(n.id)?chosen():[n];for(const note of notes)note.velocity=Math.max(.01,Math.min(1,note.velocity+(e.deltaY<0?.03:-.03)));commit();};
    $('prVelocities').onpointerdown=e=>{const hit=e.target.closest('[data-pr-velocity]');if(!hit)return;d.checkpoint();const id=hit.dataset.prVelocity,r=$('prVelocities').getBoundingClientRect(),update=e=>{const n=c.notes.find(n=>n.id===id);n.velocity=Math.max(.01,Math.min(1,(r.bottom-e.clientY)/60));selected=new Set([id]);commit();};update(e);const root=$('prVelocities');root.setPointerCapture(e.pointerId);root.onpointermove=update;root.onpointerup=()=>root.onpointermove=null;root.onpointercancel=()=>root.onpointermove=null;};
    rootNode.onkeydown=e=>{if(e.target.matches('input,select'))return;const ctrl=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();let handled=true;if(ctrl&&key==='a'){selected=new Set(c.notes.map(n=>n.id));renderNotes();}else if(ctrl&&key==='c')clipboard=chosen().map(n=>({...n}));else if(ctrl&&key==='v'&&clipboard.length){d.checkpoint();const low=Math.min(...clipboard.map(n=>n.step)),at=snapStep(engine().getPosition(),grid),copies=clipboard.map(n=>({...n,id:uid(),step:Math.max(0,n.step-low+at)}));c.notes.push(...normalizeNotes(copies,steps));selected=new Set(copies.map(n=>n.id));commit();}else if(ctrl&&key==='d')duplicate();else if(e.key==='Delete'||e.key==='Backspace'){d.checkpoint();c.notes=c.notes.filter(n=>!selected.has(n.id));selected.clear();commit();}else if(e.key==='ArrowUp'||e.key==='ArrowDown'){const delta=(e.key==='ArrowUp'?1:-1)*(e.shiftKey?12:1);applyNotes(n=>[{...n,midi:Math.max(0,Math.min(127,n.midi+delta))}]);}else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){const delta=(e.key==='ArrowRight'?1:-1)*(grid||.25);applyNotes(n=>[{...n,step:Math.max(0,Math.min(steps-n.len,n.step+delta))}]);}else if(e.altKey&&key==='q')$('prQuantize').click();else handled=false;if(handled){e.preventDefault();e.stopPropagation();}};
  }
  function finishMidi(midi,note){if(!editingClip)return;const n=editingClip.notes.find(a=>a.id===note.id);if(n){n.len=Math.max(1/96,Math.min((editingClip.patternSteps||32)-n.step,(engine().ctx.currentTime-note.time)/engine().stepDuration));commit();}}
  async function connectMidi(){if(!navigator.requestMIDIAccess){d.toast('Ce navigateur ne propose pas Web MIDI. Le piano roll reste utilisable à la souris.');return;}try{midi=await navigator.requestMIDIAccess({sysex:false});const bind=()=>{for(const input of midi.inputs.values())input.onmidimessage=({data})=>{if(!editingTrack||!editingClip)return;const [status,pitch,velocity]=data,on=(status&240)===144&&velocity>0,off=(status&240)===128||(status&240)===144&&!velocity;if(on){engine().preview(editingTrack.type,pitch,editingTrack.id);if(midiRecord){const n={id:uid(),step:Math.max(0,Math.min((editingClip.patternSteps||32)-.01,snapStep(engine().getPosition(),grid))),midi:scaleSnap?snapPitch(pitch,root,scale):pitch,len:.25,velocity:velocity/127};editingClip.notes.push(n);midiHeld.set(pitch,{id:n.id,time:engine().ctx.currentTime});commit();}}if(off&&midiHeld.has(pitch)){finishMidi(pitch,midiHeld.get(pitch));midiHeld.delete(pitch);}};};bind();midi.onstatechange=bind;d.toast(midi.inputs.size?'Clavier MIDI connecté. Active REC MIDI pour écrire le pattern.':'Aucun clavier MIDI détecté. Branche-le puis réessaie.');}catch(error){d.toast('MIDI indisponible : '+error.message);}}
  function updateFrame(){const node=$('prPlayhead');if(node&&editingClip){const step=engine().getPosition()-(engine().patternMode||engine().clipPreview?0:editingClip.start*16);node.style.left=(step%(editingClip.patternSteps||32))*stepWidth+'px';node.hidden=!engine().playing;}}
  return {render,rack,draft,updateFrame,placePattern,openChannel,bank};
}
